import {fishingImportPlan} from './fishing-import-model.mjs?v=4';
const element=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
export function initFishingImport({fish,getSnapshot,onSave}){
 const launch=element('button','Import screenshots');launch.type='button';launch.id='fish-import-open';document.querySelector('.collection-tools').append(launch);
 const dialog=element('dialog',undefined,'screenshot-import');dialog.setAttribute('aria-labelledby','fish-import-title');const header=element('header',undefined,'screenshot-import-head'),title=element('h2','Import fish screenshots');title.id='fish-import-title';const close=element('button','×');close.type='button';close.setAttribute('aria-label','Close screenshot import');header.append(title,close);
 const body=element('div',undefined,'screenshot-import-body'),intro=element('p','Choose your fish collection screenshots. Readable weights are added automatically.'),note=element('p','Images stay on this device. Records are saved in this browser. Overlapping screenshots use the highest readable weight; higher saved records stay intact.','screenshot-import-note'),label=element('label','Choose up to 6 screenshots','screenshot-import-upload'),input=element('input');input.type='file';input.accept='image/*';input.multiple=true;label.append(input);const progress=element('p','','screenshot-import-progress');progress.setAttribute('role','status');progress.setAttribute('aria-live','polite');const error=element('p','','screenshot-import-error');error.setAttribute('role','alert');const list=element('div');body.append(intro,note,label,progress,error,list);
 const footer=element('footer',undefined,'screenshot-import-actions'),undoButton=element('button','Undo last import','btn secondary'),done=element('button','Close','btn secondary');undoButton.type=done.type='button';undoButton.hidden=true;footer.append(undoButton,done);dialog.append(header,body,footer);document.body.append(dialog);
 let worker=null,waiter=null,images=[],serial=0,busy=false,undo=null;
 function free(){for(const image of images)image.close();images=[];}
 function stop(){worker?.terminate();worker=null;if(waiter){waiter.reject(Error('Import cancelled.'));waiter=null;}}
 function reset(){serial++;stop();free();input.value='';input.disabled=false;busy=false;list.replaceChildren();progress.textContent='Choose screenshots showing complete fish cards and their kg bars.';error.textContent='';undoButton.hidden=!undo;}
 function request(message,transfer=[]){return new Promise((resolve,reject)=>{waiter={resolve,reject};worker.postMessage(message,transfer);});}
 async function prepare(){worker=new Worker(new URL('./fishing-import-worker.mjs?v=4',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress'){progress.textContent='Reading fish '+data.done+' of '+data.total+'…';return;}const current=waiter;waiter=null;if(!current)return;if(data.type==='error')current.reject(Error(data.message));else current.resolve(data);};worker.onerror=()=>{waiter?.reject(Error('Image reading is unavailable in this browser. Try an updated browser.'));waiter=null;};const [manifest,atlas]=await Promise.all([fetch(new URL('./fishing-import/references.json?v=4',import.meta.url)).then(r=>{if(!r.ok)throw Error('Number references unavailable.');return r.json();}),fetch(new URL('./fishing-import/fish.webp?v=2',import.meta.url)).then(r=>{if(!r.ok)throw Error('Fish references unavailable.');return r.blob();})]);await request({type:'load',manifest,atlas,fish});}
 function results(plan){list.replaceChildren();for(const r of plan.results){const row=element('article',undefined,'screenshot-import-result'),crop=element('canvas'),box=r.record.box,bitmap=images[r.record.fileIndex];crop.width=box.w;crop.height=box.h;crop.getContext('2d').drawImage(bitmap,box.x,box.y,box.w,box.h,0,0,box.w,box.h);crop.setAttribute('role','img');crop.setAttribute('aria-label',r.name+' screenshot crop');const detail=element('div');detail.append(element('h3',r.name),element('p',r.status==='imported'?r.weight+' kg · Imported':r.status==='unchanged'?r.reason:r.status==='duplicate'?'Repeated · '+r.reason:'Skipped · '+r.reason));const matched=r.record.matches?.[0];if(matched&&r.status==='skipped'){if(r.status==='skipped'&&r.record.weight?.value)detail.append(element('small','Detected '+r.record.weight.value+' kg · not saved'));const edit=element('button','Edit weight in calculator','screenshot-import-suggest');edit.type='button';edit.onclick=()=>{reset();dialog.close();const target=document.getElementById('fish-'+matched.id);target?.scrollIntoView({block:'center'});target?.focus({preventScroll:true});};detail.append(edit);}row.append(crop,detail);list.append(row);}}
 launch.onclick=()=>{reset();dialog.showModal();};close.onclick=done.onclick=()=>{reset();dialog.close();};dialog.addEventListener('cancel',event=>{event.preventDefault();reset();dialog.close();});
 input.onchange=async()=>{const files=[...input.files];if(!files.length)return;if(files.length>6){error.textContent='Choose up to 6 screenshots at a time.';return;}reset();const token=serial,snapshot=getSnapshot();busy=true;input.disabled=undoButton.disabled=true;const records=[],failures=[];try{await prepare();for(let i=0;i<files.length;i++){if(token!==serial)return;try{if(files[i].size>12*1024*1024)throw Error('Image is larger than 12 MB.');let bitmap=await createImageBitmap(files[i]);if(bitmap.width*bitmap.height>24000000){bitmap.close();throw Error('Image resolution is too large.');}const scale=Math.min(1,1600/bitmap.width,4000/bitmap.height);if(scale<1){const resized=await createImageBitmap(bitmap,{resizeWidth:Math.round(bitmap.width*scale),resizeHeight:Math.round(bitmap.height*scale),resizeQuality:'high'});bitmap.close();bitmap=resized;}const fileIndex=images.length;images.push(bitmap);const copy=await createImageBitmap(bitmap);const result=await request({type:'scan',image:copy},[copy]);records.push(...result.records.map(r=>({...r,fileIndex})));}catch(e){if(token!==serial)return;failures.push(files[i].name+': '+e.message);}}if(token!==serial)return;const plan=fishingImportPlan(fish,snapshot.saved,records);if(plan.changes.length){onSave(plan,snapshot);undo={saved:snapshot.saved,snapshot:getSnapshot(),count:plan.changes.length};undoButton.hidden=false;}results(plan);progress.textContent=plan.changes.length+' imported · '+plan.duplicates+' repeated · '+plan.skipped+' unread · '+plan.results.filter(r=>r.status==='unchanged').length+' unchanged.';if(!records.length)failures.push('No complete fish records found. Include the fish picture and its full kg bar.');error.textContent=failures.join('\n');}catch(e){if(token===serial){progress.textContent='Import did not save.';error.textContent=e.message;}}finally{if(token===serial){busy=false;input.disabled=undoButton.disabled=false;stop();}}};
 undoButton.onclick=()=>{if(!undo||busy)return;try{onSave({next:undo.saved,changes:Array.from({length:undo.count})},undo.snapshot);undo=null;undoButton.hidden=true;list.replaceChildren();progress.textContent='Last screenshot import undone.';}catch(e){error.textContent=e.message;}};
 return {reset};
}
